// Basic transaction validation
const transaction = msg.payload;

// Check required fields
if (!transaction.amount || !transaction.currency || !transaction.merchantId) {
    msg.statusCode = 400;
    msg.payload = {
        error: 'Missing required fields',
        code: 'VALIDATION_ERROR'
    };
    return [null, msg];
}

// Validate amount
if (transaction.amount <= 0) {
    msg.statusCode = 400;
    msg.payload = {
        error: 'Invalid amount',
        code: 'INVALID_AMOUNT'
    };
    return [null, msg];
}

// Add transaction ID and timestamp
transaction.transactionId = require('crypto').randomUUID();
transaction.timestamp = new Date().toISOString();
transaction.status = 'PENDING';

msg.payload = transaction;
return [msg, null];

const routingResponse = msg.payload;
const transaction = msg.req.body;

if (routingResponse.selectedPSP) {
    // Store PSP selection in transaction
    transaction.selectedPSP = routingResponse.selectedPSP;
    transaction.routingReason = routingResponse.reason;

    msg.payload = transaction;
    return [msg, null];
} else {
    // No PSP available
    msg.statusCode = 503;
    msg.payload = {
        error: 'No PSP available',
        code: 'NO_PSP_AVAILABLE',
        transactionId: transaction.transactionId
    };
    return [null, msg];
}

// Transform internal format to Visa API format
const transaction = msg.payload;

const visaRequest = {
    systemsTraceAuditNumber: transaction.transactionId.slice(-6),
    retrievalReferenceNumber: transaction.transactionId.slice(-12),
    localTransactionDateTime: transaction.timestamp,
    acquiringBin: '408999',
    acquirerCountryCode: '840',
    primaryAccountNumber: transaction.cardNumber,
    amount: transaction.amount,
    currencyCode: getCurrencyCode(transaction.currency),
    businessApplicationId: 'AA',
    merchantCategoryCode: transaction.mcc || '5999'
};

msg.payload = visaRequest;
msg.headers = {
    'Content-Type': 'application/json',
    'Authorization': 'Bearer ' + (process.env.VISA_API_KEY || 'test-key')
};

function getCurrencyCode(currency) {
    const codes = {
        'USD': '840',
        'EUR': '978',
        'GBP': '826'
    };
    return codes[currency] || '840';
}

return msg;

// Transform Visa response to internal format
const visaResponse = msg.payload;

const response = {
    transactionId: msg.req.body.transactionId,
    status: visaResponse.responseCode === '00' ? 'APPROVED' : 'DECLINED',
    responseCode: visaResponse.responseCode,
    responseMessage: visaResponse.responseMessage,
    authorizationCode: visaResponse.authorizationIdResponse,
    pspTransactionId: visaResponse.systemsTraceAuditNumber,
    timestamp: new Date().toISOString(),
    psp: 'VISA'
};

msg.payload = response;
return msg;
